package school.chacademia.housing;
import java.util.*;import org.bukkit.Bukkit;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.player.PlayerQuitEvent;import org.bukkit.plugin.messaging.PluginMessageListener;import school.magiccodex.protocol.HousingSearchProtocol;import school.magiccodex.protocol.HousingSearchProtocol.*;
/** Coalesces requests per live player; old generations/session responses are never emitted. */
final class HousingSearchServer implements PluginMessageListener,Listener,AutoCloseable{
 final HousingPlugin plugin;final HousingPresence presence;final Map<UUID,State> states=new HashMap<>();int active;
 static final class State{final Player player;final Object session;Query latest;boolean busy,scheduled;long next,completed;State(Player p,Object session){player=p;this.session=session;}}
 HousingSearchServer(HousingPlugin plugin){this.plugin=plugin;presence=new HousingPresence(plugin);Bukkit.getMessenger().registerIncomingPluginChannel(plugin,HousingSearchProtocol.CHANNEL,this);Bukkit.getMessenger().registerOutgoingPluginChannel(plugin,HousingSearchProtocol.CHANNEL);Bukkit.getPluginManager().registerEvents(this,plugin);}
 public void onPluginMessageReceived(String channel,Player player,byte[] bytes){if(!channel.equals(HousingSearchProtocol.CHANNEL)||!plugin.rooms().searchSession(player))return;Query q;try{q=HousingSearchProtocol.query(bytes);}catch(IllegalArgumentException e){return;}var state=states.get(player.getUniqueId());if(state==null||state.session!=plugin.rooms().session(player.getUniqueId())){state=new State(player,plugin.rooms().session(player.getUniqueId()));states.put(player.getUniqueId(),state);}if(state.player!=player)return;if(state.latest!=null&&q.generation()<=state.latest.generation())return;state.latest=q;if(!state.busy)begin(state);}
 void begin(State s){if(!valid(s)||s.latest.generation()<=s.completed)return;if(active>=64){s.completed=s.latest.generation();send(s,new Page(s.latest.generation(),s.latest.page(),false,List.of(),"검색 요청이 많습니다. 잠시 후 다시 시도해 주세요."));return;}long now=System.currentTimeMillis();if(now<s.next){if(!s.scheduled){s.scheduled=true;Bukkit.getScheduler().runTaskLater(plugin,()->{s.scheduled=false;if(!s.busy)begin(s);},Math.max(1,(s.next-now+49)/50));}return;}s.next=now+300;s.busy=true;active++;var q=s.latest;presence.read(s.player,online->{if(!valid(s)){finish(s,q,null);return;}if(online==null){finish(s,q,new Page(q.generation(),q.page(),false,List.of(),"전역 접속 상태를 확인하지 못했어요. 다시 시도해 주세요."));return;}plugin.store().search(s.player.getUniqueId(),q,online,page->finish(s,q,page));});}
 boolean valid(State s){return states.get(s.player.getUniqueId())==s&&Bukkit.getPlayer(s.player.getUniqueId())==s.player&&plugin.rooms().session(s.player.getUniqueId())==s.session;}
 void finish(State s,Query q,Page page){s.busy=false;active--;if(!valid(s))return;if(s.latest!=q){begin(s);return;}s.completed=q.generation();send(s,page==null?new Page(q.generation(),q.page(),false,List.of(),"유저 검색 또는 등록 닉네임을 불러오지 못했어요."):page);}
 void send(State s,Page page){if(valid(s))s.player.sendPluginMessage(plugin,HousingSearchProtocol.CHANNEL,HousingSearchProtocol.encode(page));}
 @EventHandler public void quit(PlayerQuitEvent e){states.remove(e.getPlayer().getUniqueId());}
 public void close(){states.clear();presence.close();Bukkit.getMessenger().unregisterIncomingPluginChannel(plugin,HousingSearchProtocol.CHANNEL,this);Bukkit.getMessenger().unregisterOutgoingPluginChannel(plugin,HousingSearchProtocol.CHANNEL);}
}
